import 'package:flutter/material.dart';import 'package:uuid/uuid.dart';import '../models/models.dart';import '../services/data_service.dart';
class NewOrderScreen extends StatefulWidget{final AppUser user;const NewOrderScreen({super.key,required this.user});@override State<NewOrderScreen> createState()=>_NewState();}
class _NewState extends State<NewOrderScreen>{final ds=DataService();final lines=<OrderLine>[];String search='';List<Product> products=[];final customer=TextEditingController(),region=TextEditingController(),note=TextEditingController();
 void add(Product p){final q=TextEditingController(text:'1'),n=TextEditingController();showDialog(context:context,builder:(_)=>AlertDialog(title:Text(p.name),content:Column(mainAxisSize:MainAxisSize.min,children:[TextField(controller:q,keyboardType:TextInputType.number,decoration:const InputDecoration(labelText:'الكمية')),TextField(controller:n,decoration:const InputDecoration(labelText:'ملاحظات'))]),actions:[FilledButton(onPressed:(){setState(()=>lines.add(OrderLine(productId:p.id,productName:p.name,code:p.code,unit:p.units.isEmpty?'وحدة':p.units.first.name,quantity:double.tryParse(q.text)??1,note:n.text)));Navigator.pop(context);},child:const Text('إضافة'))]));}
 Future<void> save(OrderStatus status)async{if(lines.isEmpty)return;final now=DateTime.now();final o=OrderModel(id:const Uuid().v4(),salesRepId:widget.user.id,salesRepName:widget.user.name,status:status,lines:lines,createdAt:now,updatedAt:now,customer:customer.text,region:region.text,note:note.text);await ds.saveOrder(o);if(mounted){ScaffoldMessenger.of(context).showSnackBar(const SnackBar(content:Text('تم حفظ الطلب')));Navigator.pop(context);}}
 @override Widget build(BuildContext c)=>Scaffold(appBar:AppBar(title:const Text('طلب جديد')),body:StreamBuilder<List<Product>>(stream:ds.products(),builder:(c,s){products=s.data??[];final filtered=products.where((p)=>p.name.contains(search)||p.code.contains(search)).toList();return Column(children:[Padding(padding:const EdgeInsets.all(12),child:Column(children:[Row(children:[Expanded(child:TextField(controller:customer,decoration:const InputDecoration(labelText:'العميل'))),const SizedBox(width:8),Expanded(child:TextField(controller:region,decoration:const InputDecoration(labelText:'المنطقة')))]),const SizedBox(height:8),TextField(decoration:const InputDecoration(prefixIcon:Icon(Icons.search),hintText:'ابحث عن الصنف أو الكود'),onChanged:(v)=>setState(()=>search=v))])),Expanded(child:ListView(children:[...filtered.map((p)=>ListTile(onTap:()=>add(p),title:Text(p.name),subtitle:Text('${p.code} • ${p.units.map((x)=>x.name).join(', ')}'),trailing:const Icon(Icons.add_circle_outline))),if(lines.isNotEmpty)const Divider(),...lines.map((x)=>ListTile(title:Text(x.productName),subtitle:Text('${x.quantity} ${x.unit} ${x.note.isEmpty?'':'• '+x.note}'),trailing:IconButton(icon:const Icon(Icons.delete_outline),onPressed:()=>setState(()=>lines.remove(x))))])),bottomNavigationBar:SafeArea(child:Padding(padding:const EdgeInsets.all(12),child:Row(children:[Expanded(child:OutlinedButton(onPressed:()=>save(OrderStatus.draft),child:const Text('حفظ مسودة'))),const SizedBox(width:8),Expanded(child:FilledButton(onPressed:()=>save(OrderStatus.submitted),child:const Text('إرسال الطلب')))])));});}
}
